def _redis():
    """Lazy Upstash Redis client; None when not configured."""
    if not (UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN):
        return None
    try:
        from upstash_redis import Redis

        return Redis(url=UPSTASH_REDIS_REST_URL, token=UPSTASH_REDIS_REST_TOKEN)
    except Exception:
        return None


CHAT_USER_MAX = 24
CHAT_TEXT_MAX = 1000
CHAT_MAX_MESSAGES = 200
CHAT_DAY_TTL = 86400 * 5  
CHAT_USERS_KEY = "chat:users"


def _sanitize_name(name):
    """Make a name safe for Redis keys (keeps display case, ASCII only)."""
    allowed = string.ascii_letters + string.digits + " ._-"
    cleaned = "".join(c if c in allowed else "-" for c in name).strip()
    return cleaned[:CHAT_USER_MAX] or "anon"


def _conv_id(user, other):
    a, b = _sanitize_name(user).lower(), _sanitize_name(other).lower()
    return f"{min(a, b)}|{max(a, b)}"


def _conv_day_key(conv_id):
    return "chat:conv:" + conv_id + ":" + datetime.now(timezone.utc).strftime("%Y-%m-%d")


def _conv_index_key(user):
    return "chat:user:" + _sanitize_name(user).lower() + ":convs"


def _index_entry(conv_id, peer_display):
    return f"{conv_id}|{_sanitize_name(peer_display)}"


def _chat_message(user, text):
    return {
        "id": f"{int(time.time() * 1000)}-{secrets.token_hex(3)}",
        "user": user,
        "text": text,
        "ts": int(time.time()),
    }


def _parse_message(item):
    if isinstance(item, str):
        try:
            return json.loads(item)
        except json.JSONDecodeError:
            return None
    if isinstance(item, dict):
        return item
    return None


def _chat_unavailable():
    return (
        jsonify(
            {"error": "Chat storage not configured (set UPSTASH_REDIS_REST_URL/TOKEN)"}
        ),
        503,
    )


NAME_ALLOWED = string.ascii_letters + string.digits + " ._-"


def _clean_name(raw):
    """Validated username: ASCII letters/digits/space/dot/dash/underscore."""
    name = (raw or "").strip()
    if (
        not name
        or len(name) > CHAT_USER_MAX
        or any(c not in NAME_ALLOWED for c in name)
    ):
        return None
    return name


@app.route("/api/chat/register", methods=["POST"])
def chat_register():
    redis = _redis()
    if redis is None:
        return _chat_unavailable()
    data = request.get_json(force=True, silent=True) or {}
    user = _clean_name(data.get("user"))
    if not user:
        return jsonify({"error": "valid user is required"}), 400
    try:
        
        existing = redis.smembers(CHAT_USERS_KEY) or []
        normalized = user.casefold()
        for raw_name in existing:
            name = raw_name.decode("utf-8", errors="ignore") if isinstance(raw_name, bytes) else str(raw_name)
            if name.strip().casefold() == normalized:
                return jsonify({"error": "That username is already taken. Choose another."}), 409
        redis.sadd(CHAT_USERS_KEY, user)
    except Exception as e:
        return jsonify({"error": f"Chat store error: {e}"}), 502
    return jsonify({"ok": True, "user": user}), 201


@app.route("/api/chat/users")
def chat_users():
    redis = _redis()
    if redis is None:
        return _chat_unavailable()
    me = (request.args.get("me") or "").strip().lower()
    q = (request.args.get("q") or "").strip().lower()
    try:
        names = redis.smembers(CHAT_USERS_KEY) or []
    except Exception as e:
        return jsonify({"error": f"Chat store error: {e}"}), 502
    users = []
    for raw_name in names:
        
        
        if isinstance(raw_name, bytes):
            name = raw_name.decode("utf-8", errors="ignore")
        else:
            name = str(raw_name) if raw_name is not None else ""
        name = name.strip()
        lowered = name.lower()
        if name and lowered != me and (not q or q in lowered):
            users.append(name)
    users.sort(key=str.lower)
    return jsonify({"users": users[:50]})


@app.route("/api/chat/conversations")
def chat_conversations():
    redis = _redis()
    if redis is None:
        return _chat_unavailable()
    me = (request.args.get("user") or "").strip()
    if not me:
        return jsonify({"error": "user is required"}), 400
    try:
        entries = redis.smembers(_conv_index_key(me)) or []
    except Exception as e:
        return jsonify({"error": f"Chat store error: {e}"}), 502
    conversations = []
    for entry in entries:
        if not isinstance(entry, str) or "|" not in entry:
            continue
        conv_id, other = entry.rsplit("|", 1)
        try:
            raw = redis.lrange(_conv_day_key(conv_id), -1, -1) or []
        except Exception:
            raw = []
        preview, last_ts = "", 0
        last = _parse_message(raw[-1]) if raw else None
        if last:
            preview, last_ts = last.get("text", ""), last.get("ts", 0)
        conversations.append(
            {"type": "dm", "id": conv_id, "title": other, "preview": preview, "ts": last_ts}
        )
    conversations.sort(key=lambda c: c["ts"], reverse=True)
    return jsonify({"conversations": conversations})


@app.route("/api/chat/messages", methods=["GET"])
def chat_messages():
    redis = _redis()
    if redis is None:
        return _chat_unavailable()
    me = (request.args.get("user") or "").strip()
    other = (request.args.get("with") or "").strip()
    if not me or not other:
        return jsonify({"error": "user and with are required"}), 400
    conv_id = _conv_id(me, other)
    try:
        raw = redis.lrange(_conv_day_key(conv_id), 0, -1) or []
    except Exception as e:
        return jsonify({"error": f"Chat store error: {e}"}), 502
    messages = []
    for item in raw[-CHAT_MAX_MESSAGES:]:
        msg = _parse_message(item)
        if msg:
            messages.append(msg)
    return jsonify({"messages": messages, "conv": conv_id})


@app.route("/api/chat/delete", methods=["POST"])
def chat_delete():
    redis = _redis()
    if redis is None:
        return _chat_unavailable()
    data = request.get_json(force=True, silent=True) or {}
    user = _clean_name(data.get("user"))
    if not user:
        return jsonify({"error": "user is required"}), 400
    try:
        
        
        redis.srem(CHAT_USERS_KEY, user)
        entries = redis.smembers(_conv_index_key(user)) or []
        conv_ids = set()
        peers = set()
        for entry in entries:
            if isinstance(entry, str) and "|" in entry:
                conv_id, peer = entry.rsplit("|", 1)
                conv_ids.add(conv_id)
                peers.add(peer)
        redis.delete(_conv_index_key(user))

        
        
        for conv_id in conv_ids:
            redis.delete(_conv_day_key(conv_id))
            for peer in peers:
                redis.srem(_conv_index_key(peer), _index_entry(conv_id, user))
        
        for peer in redis.smembers(CHAT_USERS_KEY) or []:
            if isinstance(peer, str) and peer.lower() != user.lower():
                peer_entries = redis.smembers(_conv_index_key(peer)) or []
                for entry in peer_entries:
                    if isinstance(entry, str) and entry.endswith("|" + _sanitize_name(user)):
                        conv_id = entry.rsplit("|", 1)[0]
                        redis.srem(_conv_index_key(peer), entry)
                        redis.delete(_conv_day_key(conv_id))
    except Exception as e:
        return jsonify({"error": f"Chat store error: {e}"}), 502
    return jsonify({"ok": True})


@app.route("/api/chat/messages", methods=["POST"])
def chat_send():
    redis = _redis()
    if redis is None:
        return _chat_unavailable()
    data = request.get_json(force=True, silent=True) or {}
    user = _clean_name(data.get("user"))
    to = _clean_name(data.get("to"))
    text = "".join(
        ch for ch in (data.get("text") or "") if ch >= " " or ch == "\n"
    ).strip()[:CHAT_TEXT_MAX]
    if not text:
        return jsonify({"error": "Message text is required"}), 400
    if not user or not to:
        return jsonify({"error": "user and to are required"}), 400
    if user.lower() == to.lower():
        return jsonify({"error": "You can't message yourself"}), 400
    message = _chat_message(user, text)
    day_key = _conv_day_key(_conv_id(user, to))
    try:
        rl_key = (
            "chat:rl:"
            + _sanitize_name(user).lower()
            + ":"
            + str(int(time.time() // CHAT_RATE_WINDOW))
        )
        try:
            count = redis.incr(rl_key)
            redis.expire(rl_key, CHAT_RATE_WINDOW + 5)
        except Exception:
            count = 0
        if count and count > CHAT_RATE_LIMIT:
            return jsonify({"error": "Slow down you're sending too fast"}), 429
        redis.rpush(day_key, json.dumps(message))
        redis.expire(day_key, CHAT_DAY_TTL)
        conv_id = _conv_id(user, to)
        
        
        redis.sadd(CHAT_USERS_KEY, user, to)
        for owner, peer in ((user, to), (to, user)):
            idx = _conv_index_key(owner)
            redis.sadd(idx, _index_entry(conv_id, peer))
            redis.expire(idx, CHAT_DAY_TTL)
    except Exception as e:
        return jsonify({"error": f"Chat store error: {e}"}), 502
    return jsonify(message), 201


from filter import flag_text







AI_PASS_SECRET = os.environ.get("AI_PASS_SECRET") or "the-platform-ai-pass-secret"
AI_PASS_TTL = 24 * 3600  


def _mint_ai_pass():
    exp = str(int(time.time()) + AI_PASS_TTL)
    sig = hmac.new(AI_PASS_SECRET.encode("utf-8"), exp.encode("utf-8"), hashlib.sha256).hexdigest()
    return exp + "." + sig


def _check_ai_pass(value):
    try:
        raw, sig = value.split(".", 1)
        exp = int(raw)
        if exp < int(time.time()):
            return False
        want = hmac.new(AI_PASS_SECRET.encode("utf-8"), raw.encode("utf-8"), hashlib.sha256).hexdigest()
        return hmac.compare_digest(sig, want)
    except Exception:
        return False


def _ai_error_message(code, detail):
    if code == 429:
        return "The AI is busy right now (free tier is rate limited). Wait a moment and try again."
    if code == 401 or code == 403:
        return "The AI service rejected the API key. Check the AI_API_KEY environment variable."
    if code >= 500:
        return "The AI provider is having issues. Try again in a moment."
    return f"AI provider returned HTTP {code}: {detail}"


@app.route("/api/ai/chat", methods=["POST"])
def ai_chat():
    data = request.get_json(force=True, silent=True) or {}
    messages = data.get("messages") or []
    model = AI_DEFAULT_MODEL
    minted_pass = None
    if TURNSTILE_SECRET_KEY:
        verified_pass = (data.get("verified_pass") or "").strip()
        if verified_pass and _check_ai_pass(verified_pass):
            pass  
        else:
            token = (data.get("turnstile_token") or "").strip()
            if not token:
                return jsonify({"error": "Please complete the verification and try again."}), 403
            verify_req = urllib.request.Request(
                "https://challenges.cloudflare.com/turnstile/v0/siteverify",
                data=json.dumps({"secret": TURNSTILE_SECRET_KEY, "response": token, "remoteip": request.remote_addr}).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            try:
                with urllib.request.urlopen(verify_req, timeout=8) as verify_resp:
                    verification = json.loads(verify_resp.read().decode("utf-8"))
            except Exception:
                return jsonify({"error": "Verification service unavailable. Please try again."}), 503
            if not verification.get("success"):
                return jsonify({"error": "Verification failed. Please try again."}), 403  
            minted_pass = _mint_ai_pass()
    if not messages:
        return jsonify({"error": "No messages provided"}), 400

    
    last_user = ""
    for m in reversed(messages):
        if isinstance(m, dict) and m.get("role") == "user" and m.get("content"):
            last_user = m["content"]
            break
    bad = flag_text(last_user)

    def moderate_flagged_message(text, flagged_term):
        moderation_model = os.environ.get("AI_MODERATION_MODEL", "openrouter/free")
        moderation_prompt = (
            "You are a permissive safety classifier. Review the message in context. "
            "Allow clearly innocent meanings, including food, programming, music, or "
            "ordinary conversation. Block only strong evidence of sexual exploitation, "
            "hateful abuse, threats, self-harm encouragement, or illegal wrongdoing. "
            "Return JSON only with an allow boolean and no markdown.\\n"
            "Flagged term: " + str(flagged_term) + "\\nMessage: " + str(text)
        )
        moderation_payload = {
            "model": moderation_model,
            "messages": [
                {"role": "system", "content": "Classify safety context. Return JSON only."},
                {"role": "user", "content": moderation_prompt},
            ],
            "max_tokens": 40,
            "temperature": 0,
        }
        moderation_req = urllib.request.Request(
            AI_BASE_URL + "/chat/completions",
            data=json.dumps(moderation_payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                **({"Authorization": f"Bearer {AI_API_KEY}"} if AI_API_KEY else {}),
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(moderation_req, timeout=15) as moderation_resp:
                moderation_body = json.loads(moderation_resp.read().decode("utf-8"))
            raw = (((moderation_body.get("choices") or [{}])[0].get("message") or {}).get("content") or "")
            parsed = json.loads(raw.strip().replace("```json", "").replace("```", "").strip())
            return parsed.get("allow") is True
        except Exception:
            return False

    if bad and not moderate_flagged_message(last_user, bad):
        return jsonify({"error": "That message was blocked by the safety filter."}), 400

    candidates = [AI_DEFAULT_MODEL]
    backup_model = os.environ.get("AI_BACKUP_MODEL", "nvidia/nemotron-3-ultra-550b-a55b:free")
    if backup_model and backup_model != AI_DEFAULT_MODEL:
        candidates.append(backup_model)
    body = None
    last_error = None
    used_model = AI_DEFAULT_MODEL
    for candidate in candidates:
        used_model = candidate
        payload = {"model": candidate, "messages": messages, "max_tokens": 1800}
        headers = {"Content-Type": "application/json"}
        if AI_API_KEY:
            headers["Authorization"] = f"Bearer {AI_API_KEY}"
            headers["HTTP-Referer"] = request.host_url.rstrip("/")
            headers["X-Title"] = "The Platform"
        req = urllib.request.Request(
            AI_BASE_URL + "/chat/completions",
            data=json.dumps(payload).encode("utf-8"),
            headers=headers,
            method="POST",
        )
        retry_deadline = time.time() + 40
        attempt = 0
        while time.time() < retry_deadline:
            attempt += 1
            try:
                with urllib.request.urlopen(req, timeout=50) as resp:
                    body = json.loads(resp.read().decode("utf-8"))
                break
            except urllib.error.HTTPError as e:
                last_error = e
                full = ""
                try:
                    full = e.read().decode("utf-8", errors="replace")
                except Exception:
                    pass
                detail = full[:300]
                retriable = e.code in (408, 425, 429, 500, 502, 503, 504)
                if not retriable:
                    if candidate == candidates[-1]:
                        return jsonify({"error": _ai_error_message(e.code, detail)}), 502
                    break
                wait = None
                if e.code == 429:
                    try:
                        wait = float((json.loads(full).get("error") or {}).get("metadata", {}).get("retry_after_seconds", 0))
                    except Exception:
                        wait = None
                    try:
                        ha = e.headers.get("Retry-After") if e.headers else None
                        if ha:
                            wait = float(ha)
                    except (TypeError, ValueError, AttributeError):
                        pass
                if not wait or wait <= 0 or wait > 12:
                    wait = min(0.8 * attempt, 5)
                if time.time() + wait >= retry_deadline:
                    break
                time.sleep(wait)
            except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as e:
                last_error = e
                wait = min(0.8 * attempt, 5)
                if time.time() + wait >= retry_deadline:
                    break
                time.sleep(wait)
            except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as e:
                last_error = e
                if attempt == 2:
                    break
                time.sleep(0.6 * (attempt + 1))
        if body is not None:
            break

    if body is None:
        return jsonify({"error": "AI is unavailable right now. Please try again."}), 503

    try:
        choice = body.get("choices") or [{}]
        content = (choice[0].get("message") or {}).get("content") or ""
        
        
        
        content = re.sub(r"(?im)^\s*(user safety|response safety):[^\n]*\n?", "", content).strip()
        if not content:
            
            
            for retry in range(2):
                time.sleep(0.6 * (retry + 1))
                try:
                    with urllib.request.urlopen(req, timeout=50) as retry_resp:
                        retry_body = json.loads(retry_resp.read().decode("utf-8"))
                    retry_choice = retry_body.get("choices") or [{}]
                    content = (retry_choice[0].get("message") or {}).get("content") or ""
                    content = re.sub(r"(?im)^\s*(user safety|response safety):[^\n]*\n?", "", content).strip()
                    if content:
                        body = retry_body
                        break
                except Exception:
                    continue
        if not content:
            return jsonify({"error": "AI is unavailable right now. Please try again."}), 503
        bad_reply = flag_text(content)
        if bad_reply:
            content = (
                "I can't answer that one my response would have contained "
                "inappropriate content. Ask me something else."
            )
        out = {"reply": content, "model": body.get("model", used_model)}
        if minted_pass:
            out["pass"] = minted_pass
        return jsonify(out)
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", errors="replace")[:300]
        return jsonify({"error": _ai_error_message(e.code, detail)}), 502
    except Exception as e:
        return (
            jsonify(
                {
                    "error": (
                        f"Can't reach the AI API at {AI_BASE_URL} ({e}). "
                        "Set AI_BASE_URL / AI_API_KEY to point at an OpenAI compatible API."
                    )
                }
            ),
            502,
        )


@app.route("/api/ai/status")
def ai_status():
    try:
        headers = {}
        if AI_API_KEY:
            headers["Authorization"] = f"Bearer {AI_API_KEY}"
        req = urllib.request.Request(
            AI_BASE_URL + "/models",
            headers=headers,
        )
        with urllib.request.urlopen(req, timeout=5) as resp:
            body = json.loads(resp.read().decode("utf-8"))
        models = body.get("data") or []

        def _is_zero(v):
            try:
                return float(v) == 0
            except (TypeError, ValueError):
                return False

        
        free_ids = []
        for m in models:
            if not isinstance(m, dict) or not m.get("id"):
                continue
            p = m.get("pricing") or {}
            if _is_zero(p.get("prompt")) and _is_zero(p.get("completion")):
                free_ids.append(m["id"])
        free_ids = sorted(free_ids)
        return jsonify(
            {
                "ok": True,
                "models": len(models),
                "free": len(free_ids),
                "ids": free_ids,
                "url": AI_BASE_URL,
            }
        )
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "url": AI_BASE_URL})


@app.after_request
def _security_headers(resp):
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "SAMEORIGIN"
    resp.headers["Referrer-Policy"] = "no-referrer"
    resp.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
    resp.headers["Cross-Origin-Opener-Policy"] = "same-origin"
    resp.headers["Cross-Origin-Resource-Policy"] = "same-origin"
    resp.headers["Permissions-Policy"] = (
        "camera=(), microphone=(), geolocation=(), payment=(), usb=(), "
        "gyroscope=(), accelerometer=(), magnetometer=()"
    )
    if resp.status_code == 200 and resp.mimetype == "text/html":
        resp.headers["Cache-Control"] = "public, max-age=60"
    resp.headers["Content-Security-Policy"] = (
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline' https://challenges.cloudflare.com; "
        "style-src 'self' 'unsafe-inline'; "
        "img-src 'self' data:; "
        "connect-src 'self' https://challenges.cloudflare.com; "
        "frame-src 'self' https://challenges.cloudflare.com; "
        "manifest-src 'self'; "
        "object-src 'none'; "
        "base-uri 'self'; "
        "form-action 'self'; "
        "frame-ancestors 'self'"
    )
    return resp



ALLOWED_API_ORIGINS = {
    "https://theplatform-app.vercel.app",
    "https://the-platform-alt.vercel.app",
    "https://Arnsgaming8.github.io",
}


def _origin_allowed(origin):
    return bool(origin) and origin.rstrip("/").lower() in {o.lower() for o in ALLOWED_API_ORIGINS}


@app.after_request
def _cors_headers(resp):
    origin = request.headers.get("Origin")
    if _origin_allowed(origin):
        resp.headers["Access-Control-Allow-Origin"] = origin
        resp.headers["Vary"] = "Origin"
        resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
        resp.headers["Access-Control-Allow-Headers"] = "Content-Type"
        resp.headers["Access-Control-Max-Age"] = "86400"
    return resp


@app.before_request
def _cors_preflight():
    if request.method == "OPTIONS":
        origin = request.headers.get("Origin")
        if _origin_allowed(origin):
            resp = app.make_response("")
            resp.status_code = 204
            resp.headers["Access-Control-Allow-Origin"] = origin
            resp.headers["Vary"] = "Origin"
            resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
            resp.headers["Access-Control-Allow-Headers"] = "Content-Type"
            resp.headers["Access-Control-Max-Age"] = "86400"
            return resp
    return None




